{
  "title": "Platform-Wide and Course-Specific Analytics and Reporting",
  "functional_domain": "This cluster provides comprehensive analytics and reporting capabilities for a learning platform, encompassing platform-wide usage statistics, detailed course performance metrics, and a robust system for generating custom reports. It serves as the central hub for administrators and stakeholders to gain insights into user activity, course engagement, and overall platform health.",
  "sections": [
    {
      "title": "Overview and Core Components",
      "description": "The 'Platform-Wide and Course-Specific Analytics and Reporting' feature cluster is a comprehensive system designed to provide deep insights into user activity, course performance, and overall platform usage. Managed primarily through the `admin` namespace controllers, this cluster integrates data from various microservices and internal models to deliver a unified view of the learning platform's operational and educational metrics.",
      "components": [
        {
          "name": "Admin::StatisticsController",
          "source": "app/controllers/admin/statistics_controller.rb",
          "responsibility": "Serves as the primary entry point for the statistics dashboard, setting up the overall navigation and context."
        },
        {
          "name": "Course::Admin::StatisticsController",
          "source": "Merged Source 1",
          "responsibility": "Provides an administrative interface or specific statistics views related to courses, complementing the general `Admin::StatisticsController`."
        },
        {
          "name": "Admin::StatisticsPresenter",
          "source": "app/presenters/admin/statistics_presenter.rb",
          "responsibility": "Assists in formatting and presenting course-related data for the dashboard."
        }
      ]
    },
    {
      "title": "Platform-Wide Statistics",
      "description": "Platform-level insights are aggregated and served by the `Admin::Ajax::PlatformStatisticsController`. These statistics are aggressively cached using `Rails.cache` for performance, with expiration times ranging from 30 minutes to 1 hour.",
      "components": [
        {
          "name": "Admin::Ajax::PlatformStatisticsController",
          "source": "app/controllers/admin/ajax/platform_statistics_controller.rb",
          "responsibility": "Responsible for fetching and aggregating platform-level statistics."
        }
      ],
      "features": [
        {
          "name": "Learners and Enrollments",
          "details": "Gathers data on confirmed users, deleted users, total enrollments, and course counts by making concurrent calls to `account_api` and `course_api` using `Restify::Promise`. Incorporates `Xikolo.config.global_enrollment_delta` and `Xikolo.config.global_users_delta` for adjustments."
        },
        {
          "name": "Activity",
          "details": "Reports active user counts for the last 24 hours and 7 days by calling a generic `fetch_metric` function, which interacts with the `lanalytics_api`."
        },
        {
          "name": "Certificates",
          "details": "Provides counts for 'Record of Achievement' (ROA) and 'Confirmation of Participation' (COP) certificates, also fetched via `fetch_metric` from `lanalytics_api`."
        }
      ]
    },
    {
      "title": "Course-Specific Statistics",
      "description": "Detailed analytics for individual courses are provided by the `Admin::Ajax::DetailStatisticsController`. These detail statistics also leverage `Rails.cache` for performance.",
      "components": [
        {
          "name": "Admin::Ajax::DetailStatisticsController",
          "source": "app/controllers/admin/ajax/detail_statistics_controller.rb",
          "responsibility": "Provides detailed analytics for individual courses."
        },
        {
          "name": "GeoIP::Lookup",
          "source": "lib/geo_ip/lookup.rb",
          "responsibility": "Module available for resolving IP addresses to geographical locations, suggesting how geographical data might be collected or enriched by the analytics service."
        }
      ],
      "features": [
        {
          "name": "Geographical Data",
          "details": "Fetches `top_countries` and `top_cities` based on user activity within a specified course and date range. This data is cached."
        },
        {
          "name": "Top Item Types",
          "details": "Aggregates visits by content type or exercise type for course items. It first retrieves all items for a course from `course_api` and then fetches `top_items` metrics, combining them to present a summary of item type visits."
        },
        {
          "name": "Videos",
          "details": "Retrieves `video_statistics` for a given course from `lanalytics_api`."
        },
        {
          "name": "Most Active Users",
          "details": "If the `teaching_team_pinboard_activity` beta feature is enabled, it fetches the most active users on the course pinboard from `pinboard_api`."
        }
      ]
    },
    {
      "title": "Course Model Statistics (Core Business Logic)",
      "description": "Beyond the administrative AJAX controllers, the `Course::Statistics` model provides core business logic for course-level metrics.",
      "components": [
        {
          "name": "Course::Statistics",
          "source": "app/models/course/statistics.rb",
          "responsibility": "Provides core business logic for course-level metrics."
        },
        {
          "name": "Course::EnrollmentsStatistics",
          "source": "app/models/course/enrollments_statistics.rb",
          "responsibility": "Calculates current, start-date, and end-date enrollments, accounting for an `enrollment_delta` stored on the `Course` model."
        }
      ],
      "features": [
        {
          "name": "Enrollment Statistics",
          "details": "Delegates to `Course::EnrollmentsStatistics` to calculate current, start-date, and end-date enrollments, accounting for an `enrollment_delta` stored on the `Course` model."
        },
        {
          "name": "Shows at Middle",
          "details": "Determines the number of distinct users who visited at least one course item by the middle of the course, using `Course::Visit` records."
        },
        {
          "name": "Completion Rate",
          "details": "Calculates the percentage of users who achieved a 'Record of Achievement' (ROA) relative to the 'shows at middle' count."
        },
        {
          "name": "Certificate Counts",
          "details": "Fetches ROA and COP counts from the `lanalytics_api` for the specific course, with caching."
        }
      ]
    },
    {
      "title": "Report Generation and Management",
      "description": "The `Admin::ReportsController` is the central hub for users to create, manage, and download custom reports.",
      "components": [
        {
          "name": "Admin::ReportsController",
          "source": "app/controllers/admin/reports_controller.rb",
          "responsibility": "Central hub for users to create, manage, and download custom reports."
        },
        {
          "name": "Admin::ReportJobPresenter",
          "source": "app/presenters/admin/report_job_presenter.rb",
          "responsibility": "Presents existing report jobs fetched asynchronously via AJAX from `lanalytics_api`."
        },
        {
          "name": "Admin::ReportPresenter",
          "source": "app/presenters/admin/report_presenter.rb",
          "responsibility": "Used to format and display available report types and their configurable options, dynamically populating select fields with courses and classifiers."
        }
      ],
      "features": [
        {
          "name": "Report Job Listing",
          "details": "Lists existing report jobs, fetched asynchronously via AJAX from `lanalytics_api` and presented using `Admin::ReportJobPresenter`."
        },
        {
          "name": "Report Creation",
          "details": "Users can create new report jobs by selecting a `task_type`, `task_scope`, and various `options`. These options can include course selection (fetched from `course_api`) and classifier selection (from `Course::Classifier`)."
        },
        {
          "name": "Job Management",
          "details": "The controller handles restarting failed jobs and deleting completed or failed jobs, interacting with `lanalytics_api`."
        }
      ],
      "permissions": [
        {
          "name": "lanalytics.report.create",
          "details": "Permission required to create new reports."
        },
        {
          "name": "lanalytics.report.delete",
          "details": "Permission required to delete reports."
        },
        {
          "name": "lanalytics.report.admin",
          "details": "A role encompassing both create and delete permissions, manually grantable/revocable via Rails console in `xi-account` service."
        }
      ]
    },
    {
      "title": "Auxiliary Components and Interactions",
      "description": "Various AJAX endpoints and helper modules support the analytics and reporting functionality.",
      "components": [
        {
          "name": "Admin::Ajax::ClassifiersController",
          "source": "app/controllers/admin/ajax/classifiers_controller.rb",
          "responsibility": "Provides AJAX endpoints to fetch data for dropdowns and auto-completion fields."
        },
        {
          "name": "Admin::Ajax::CoursesController",
          "source": "app/controllers/admin/ajax/courses_controller.rb",
          "responsibility": "Provides AJAX endpoints to fetch data for dropdowns and auto-completion fields."
        },
        {
          "name": "Admin::Ajax::UsersController",
          "source": "app/controllers/admin/ajax/users_controller.rb",
          "responsibility": "Provides AJAX endpoints to fetch data for dropdowns and auto-completion fields."
        },
        {
          "name": "Admin::Ajax::StreamsController",
          "source": "app/controllers/admin/ajax/streams_controller.rb",
          "responsibility": "Provides AJAX endpoints to fetch data for dropdowns and auto-completion fields."
        },
        {
          "name": "LanalyticsHelper",
          "source": "app/helpers/lanalytics_helper.rb",
          "responsibility": "Provides `lanalytics_data` for frontend consumption, including user ID and build version."
        }
      ],
      "key_interactions": [
        "`account_api`",
        "`course_api`",
        "`lanalytics_api`",
        "`pinboard_api`",
        "`Restify::Promise`",
        "`Rails.cache`",
        "`GeoIP::Lookup`"
      ]
    },
    {
      "title": "Technical Debt",
